76	@RestController
77	@CrossOrigin(exposedHeaders = "errors, content-type")
78	@RequestMapping("/api")
79	public class OwnerRestControllerV1 implements OwnersApi {
80	
81	    /** Dedicated audit logger; emits one line per successful owner create. */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    /** Dedicated notification logger; emits one welcome line per successful owner create. */
85	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
86	
87	    /**
88	     * Process-wide, monotonically increasing sequence stamped onto each structured
89	     * {@code OWNER_CREATED} audit event so consumers can order and de-duplicate them.
90	     */
91	    private static final AtomicLong AUDIT_EVENT_SEQ = new AtomicLong();
92	
93	    /** Serializes structured audit events to compact JSON. */
94	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
95	
96	    private final ClinicService clinicService;
97	
98	    private final OwnerMapper ownerMapper;
99	
100	    private final PetMapper petMapper;
101	
102	    private final VisitMapper visitMapper;
103	
104	    /** HTTP header carrying the caller-supplied idempotency key for owner creates. */
105	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
106	
107	    /**
108	     * Records the owner created for each previously-seen idempotency key, so a create that repeats a
109	     * key returns the originally created owner instead of creating a duplicate. Keyed by the raw
110	     * header value; the stored value is the response returned for the first successful create.
111	     */
112	    private final Map<String, OwnerDto> idempotentCreations = new ConcurrentHashMap<>();
113	
114	    public OwnerRestControllerV1(ClinicService clinicService,
115	                                 OwnerMapper ownerMapper,
116	                                 PetMapper petMapper,
117	                                 VisitMapper visitMapper) {
118	        this.clinicService = clinicService;
119	        this.ownerMapper = ownerMapper;
120	        this.petMapper = petMapper;
121	        this.visitMapper = visitMapper;
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
127	        Collection<Owner> owners;
128	        if (lastName != null) {
129	            owners = this.clinicService.findOwnerByLastName(lastName);
130	        } else {
131	            owners = this.clinicService.findAllOwners();
132	        }
133	        if (owners.isEmpty()) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
142	        Owner owner = this.clinicService.findOwnerById(ownerId);
143	        if (owner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
152	        // Idempotent create: when the request carries an 'Idempotency-Key' header that we have already
153	        // seen, return the owner originally created for that key with 200 instead of creating a
154	        // duplicate (which would otherwise be rejected as a 409 conflict). A brand-new key is recorded
155	        // below once the create succeeds; a request without the header is never treated as idempotent.
156	        String idempotencyKey = currentIdempotencyKey();
157	        if (idempotencyKey != null) {
158	            OwnerDto existing = idempotentCreations.get(idempotencyKey);
159	            if (existing != null) {
160	                return new ResponseEntity<>(existing, HttpStatus.OK);
161	            }
162	        }
163	        // Normalize the address up front so every downstream use (the required-field check,
164	        // household-duplicate detection, the shared household id and the stored/returned value)
165	        // works from the same canonical form. The structured 'addressLine1'/'addressLine2' fields are
166	        // preferred when present; the flat 'address' remains accepted for backward compatibility. Each
167	        // supplied line is normalized the same way, and the composed address is the normalized
168	        // addressLine1 with a single space and the normalized addressLine2 appended when present.
169	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
170	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
171	        boolean structuredAddress = !isBlank(normalizedAddressLine1);
172	        String normalizedAddress;
173	        if (structuredAddress) {
174	            normalizedAddress = normalizedAddressLine2.isEmpty()
175	                ? normalizedAddressLine1
176	                : normalizedAddressLine1 + " " + normalizedAddressLine2;
177	        } else {
178	            normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
179	        }
180	        List<String> missingFields = new ArrayList<>();
181	        if (isBlank(ownerFieldsDto.getFirstName())) {
182	            missingFields.add("firstName");
183	        }
184	        if (isBlank(ownerFieldsDto.getLastName())) {
185	            missingFields.add("lastName");
186	        }
187	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
188	        if (isBlank(normalizedAddress)) {
189	            missingFields.add("address");
190	        }
191	        if (isBlank(ownerFieldsDto.getCity())) {
192	            missingFields.add("city");
193	        }
194	        if (isBlank(ownerFieldsDto.getTelephone())) {
195	            missingFields.add("telephone");
196	        }
197	        if (!missingFields.isEmpty()) {
198	            throw new InvalidOwnerFieldsException(missingFields);
199	        }
200	        // A supplied registration date may not lie in the future: reject with 400 when the caller
201	        // provides a date later than the server's current date. Checked against the raw supplied value
202	        // (before any business-day adjustment) so a future date is never silently accepted.
203	        if (ownerFieldsDto.getRegistrationDate() != null
204	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
205	            throw new FutureRegistrationDateException(ownerFieldsDto.getRegistrationDate());
206	        }
207	        // Determine the effective registration date up front so every downstream use (the daily
208	        // create-limit, the stored value and anything derived from it such as the membership number's
209	        // year segment) works from the same business-day-adjusted date. The effective date is the
210	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
211	        // forward to the following Monday.
212	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
213	            ? ownerFieldsDto.getRegistrationDate()
214	            : LocalDate.now();
215	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
216	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
217	        // already carry this adjusted business day's registration date, no further owners may be
218	        // created for that day.
219	        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
220	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
221	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
222	        }
223	        // Flag a bulk signup once more than 80 owners have already been created for this
224	        // business day, sharing the same daily accumulation path as the create-limit rule above.
225	        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
226	        // Reject the request when the owner's city is already full: a city that already holds the
227	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
228	        int ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
229	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
230	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
231	        }
232	        // Flag a capacity warning when the owner's city is approaching the per-city limit: it already
233	        // holds between 40 and 49 owners (the hard rejection at 50 above is unchanged).
234	        boolean capacityWarning = ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD;
235	        // Postcode is optional; when present it must be a 4-digit value that is valid for the
236	        // owner's city per the fixed region ranges. A malformed or out-of-range postcode is
237	        // rejected with a 400. An absent postcode leaves the request contract unchanged.
238	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
239	        // Normalize the telephone into E.164 form; a number that cannot form a valid
240	        // E.164 value is rejected with a 400.
241	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
242	        // Email is optional; when present it must be a syntactically valid address and is
243	        // stored lower-cased. An invalid address is rejected with a 400.
244	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
245	        // Derive the household id up front. It is a deterministic function of the normalized last name
246	        // and the postcode, so owners sharing a last name and postcode independently derive the same
247	        // value and are the same household. It is always computed (never null), regardless of whether
248	        // the caller opts into a shared household; 'sharesHousehold' now only bypasses the household
249	        // duplicate block below.
250	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
251	        String householdId = householdId(normalizedLastName, ownerFieldsDto.getPostcode());
252	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
253	        // All duplicate detection is consolidated into a single derived identity key: the SHA-256 hex
254	        // over 'normalizedTelephone + | + lowerEmail + | + soundex(lastName)'. Because the telephone is
255	        // part of the key, two members of the same household (same last name and postcode) with
256	        // different telephones have different keys and are both allowed; only an exact whole-key match
257	        // is a duplicate. The email-domain blocklist has already been applied (during email
258	        // normalization above). Reject with 409 when a new owner's whole identity key equals an
259	        // existing (non-deleted) owner's. The computed householdId no longer contributes a separate
260	        // duplicate block; it is retained only for household grouping (size, level cap, points).
261	        String identityKey = identityKey(normalizedTelephone, normalizedEmail, ownerFieldsDto.getLastName());
262	        boolean identityInUse = this.clinicService.findAllOwners().stream()
263	            .filter(existing -> !existing.isDeleted())
264	            .anyMatch(existing -> identityKey.equals(
265	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getLastName())));
266	        if (identityInUse) {
267	            throw new DuplicateOwnerIdentityException(identityKey);
268	        }
269	        HttpHeaders headers = new HttpHeaders();
270	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
271	        // Store the composed, normalized address plus the normalized structured lines. The structured
272	        // lines are only retained when the owner was supplied in the structured form; a flat-address
273	        // owner keeps them null.
274	        owner.setAddress(normalizedAddress);
275	        owner.setAddressLine1(structuredAddress ? normalizedAddressLine1 : null);
276	        owner.setAddressLine2(structuredAddress && !normalizedAddressLine2.isEmpty()
277	            ? normalizedAddressLine2 : null);
278	        owner.setTelephone(normalizedTelephone);
279	        owner.setEmail(normalizedEmail);
280	        owner.setHouseholdId(householdId);
281	        // Record how many existing owners (before this create) share this owner's first and last
282	        // name, compared case-insensitively. Computed against the current owners so the new owner
283	        // itself is never counted.
284	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
285	        // Record the size of this owner's household (owners sharing the same householdId) after this
286	        // create: the existing members already stamped with the shared identifier plus this new
287	        // owner. An owner not admitted into any household is a household of one.
288	        owner.setHouseholdSize(countHouseholdMembers(householdId) + 1);
289	        // Cap the new owner's membership level at one above the current maximum membership level
290	        // among their existing household members (members already carrying this household id). The cap
291	        // applies to an owner joining an existing household on their own; an explicitly declared
292	        // 'sharesHousehold' member keeps its full points-based level. When there is no existing
293	        // household member, no cap applies and the level is left uncapped.
294	        owner.setMembershipLevelCap(sharesHousehold ? null : householdMembershipLevelCap(householdId));
295	        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
296	        owner.setBulkSignupWarning(bulkSignupWarning);
297	        // Persist the capacity-warning flag computed above so it is returned on subsequent reads.
298	        owner.setCapacityWarning(capacityWarning);
299	        // Store the business-day-adjusted effective registration date computed above. This defaults
300	        // to the server's current date when none was supplied and rolls any weekend date forward to
301	        // the following Monday, so everything derived from it (e.g. the membership number's year
302	        // segment) uses the adjusted date.
303	        owner.setRegistrationDate(effectiveRegistrationDate);
304	        // Assign the unified member id: '<REGION><FY><HASH8><CHK>' where REGION is the region derived
305	        // from the owner's postcode (falling back to the city-to-region table, else 'UNKNOWN', matching
306	        // the locality derivation), FY is the 2-digit fiscal year of the (already business-day-adjusted)
307	        // registration date, HASH8 is the first 8 upper-case hex characters of
308	        // SHA-256(normalizedTelephone + lastName), and CHK is a single Luhn check digit over the digits
309	        // of '<REGION><FY><HASH8>'. Compute the base value, then de-duplicate it: if it collides with an
310	        // existing owner's memberId, append '-<n>' using the smallest n of 2 or more that yields a value
311	        // no existing owner already carries.
312	        owner.setMemberId(deduplicateMemberId(memberId(
313	            deriveRegion(owner.getPostcode(), owner.getCity()),
314	            effectiveRegistrationDate, normalizedTelephone, owner.getLastName())));
315	        // Soft-match detection: an owner that cleared the hard-duplicate check above may still
316	        // resemble an existing owner when its identity key differs but it shares that owner's
317	        // soundex(lastName) and postcode (a different telephone, and now a same-household-but-distinct
318	        // registration, both land here rather than being rejected). A declared household member
319	        // ('sharesHousehold') is never a suspected duplicate, so it is exempt. Flag a matched owner as
320	        // a possible duplicate, recording its id; otherwise the flag is false with no matched id.
321	        Owner possibleDuplicateOwner = sharesHousehold ? null : findPossibleDuplicate(
322	            owner.getLastName(), owner.getPostcode(), identityKey);
323	        owner.setPossibleDuplicate(possibleDuplicateOwner != null);
324	        owner.setPossibleDuplicateOf(possibleDuplicateOwner == null ? null : possibleDuplicateOwner.getId());
325	        this.clinicService.saveOwner(owner);
326	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
327	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
328	        // member id, the effective registration date and the numeric membership level.
329	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
330	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
331	        // Alongside the human-readable line, publish an immutable, machine-readable event describing
332	        // the create: a JSON object stamped with a process-wide monotonically increasing sequence, the
333	        // owner id, the owner's current primary identifier (the unified memberId) and its numeric
334	        // membership level.
335	        Map<String, Object> ownerCreatedEvent = new LinkedHashMap<>();
336	        ownerCreatedEvent.put("seq", AUDIT_EVENT_SEQ.incrementAndGet());
337	        ownerCreatedEvent.put("ownerId", owner.getId());
338	        ownerCreatedEvent.put("memberId", owner.getMemberId());
339	        ownerCreatedEvent.put("membershipLevel", ownerDto.getMembershipLevel());
340	        ownerCreatedEvent.put("event", "OWNER_CREATED");
341	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(ownerCreatedEvent));
342	        // Enqueue a welcome notification for the newly created owner: a NOTIFY line carrying the
343	        // owner id and its assigned member id.
344	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
345	        headers.setLocation(UriComponentsBuilder.newInstance()
346	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
347	        // Remember the created owner against its idempotency key (when one was supplied) so a later
348	        // create repeating the same key returns this same owner rather than creating a duplicate.
349	        if (idempotencyKey != null) {
350	            idempotentCreations.put(idempotencyKey, ownerDto);
351	        }
352	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
353	    }
