453	    /**
454	     * Read the {@code Idempotency-Key} header from the current request, or {@code null} when the
455	     * header is absent, blank, or no request is bound to the thread. The header is not part of the
456	     * generated API signature, so it is read from the ambient request rather than a method parameter.
457	     */
458	    private static String currentIdempotencyKey() {
459	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
460	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
461	            return null;
462	        }
463	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
464	        return isBlank(key) ? null : key;
465	    }
466	
467	    private static boolean isBlank(String value) {
468	        return value == null || value.trim().isEmpty();
469	    }
470	
471	    /**
472	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
473	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
474	     * compared case-insensitively with collapsed whitespace.
475	     */
476	    private static String collapse(String value) {
477	        if (value == null) {
478	            return "";
479	        }
480	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
481	    }
482	
483	    /**
484	     * Common street-type abbreviations expanded during address normalization.
485	     */
486	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
487	        "ST", "STREET",
488	        "RD", "ROAD",
489	        "AVE", "AVENUE");
490	
491	    /**
492	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
493	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
494	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
495	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
496	     * address maps to itself.
497	     */
498	    private static String normalizeAddress(String value) {
499	        if (value == null) {
500	            return "";
501	        }
502	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
503	        if (collapsed.isEmpty()) {
504	            return "";
505	        }
506	        String[] tokens = collapsed.split(" ");
507	        StringBuilder sb = new StringBuilder(collapsed.length());
508	        for (int i = 0; i < tokens.length; i++) {
509	            if (i > 0) {
510	                sb.append(' ');
511	            }
512	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
513	        }
514	        return sb.toString();
515	    }
516	
517	    /**
518	     * Derive the stable household identifier shared by owners with the same normalized last name
519	     * and postcode. It is a deterministic function of those two values, so every member of a
520	     * household independently derives the same identifier: the first 12 upper-case hex characters
521	     * of {@code SHA-256(normalizedLastName + '|' + postcode)}. A {@code null} postcode contributes
522	     * an empty segment.
523	     */
524	    private static String householdId(String normalizedLastName, String postcode) {
525	        try {
526	            byte[] digest = MessageDigest.getInstance("SHA-256")
527	                .digest((normalizedLastName + "|" + (postcode == null ? "" : postcode))
528	                    .getBytes(StandardCharsets.UTF_8));
529	            StringBuilder sb = new StringBuilder(digest.length * 2);
530	            for (byte b : digest) {
531	                sb.append(String.format("%02x", b));
532	            }
533	            return sb.substring(0, 12).toUpperCase();
534	        }
535	        catch (NoSuchAlgorithmException e) {
536	            throw new IllegalStateException("SHA-256 not available", e);
537	        }
538	    }
539	
540	    /**
541	     * Derive the identity key into which all duplicate detection is consolidated: the full lower-case
542	     * hex SHA-256 over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. A
543	     * null email or last name contributes an empty segment. Two owners are duplicates only when their
544	     * whole identity keys are equal. Delegates to {@link IdentityKeys#identityKey} so the value here
545	     * matches the one the mapper exposes on the owner DTO.
546	     */
547	    private static String identityKey(String telephone, String email, String lastName) {
548	        return IdentityKeys.identityKey(telephone, email, lastName);
549	    }
