551	    /**
552	     * Count the existing owners that share the given first and last name, compared
553	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
554	     * namesakes that already existed at creation time (the new owner itself is not included).
555	     */
556	    private int countNamesakes(String firstName, String lastName) {
557	        return (int) this.clinicService.findAllOwners().stream()
558	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
559	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
560	                && existing.getLastName().equalsIgnoreCase(lastName))
561	            .count();
562	    }
563	
564	    /**
565	     * Count the existing owners that already belong to the given household (i.e. carry the same
566	     * non-null householdId). Called after any existing members have been backfilled with the shared
567	     * identifier but before the new owner is saved, so the returned value reflects the members that
568	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
569	     * new owner is not part of any household ({@code householdId} is null).
570	     */
571	    private int countHouseholdMembers(String householdId) {
572	        if (householdId == null) {
573	            return 0;
574	        }
575	        return (int) this.clinicService.findAllOwners().stream()
576	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
577	            .count();
578	    }
579	
580	    /**
581	     * Compute the membership-level cap for a new owner joining the given household: one above the
582	     * current maximum membership level among the existing (non-deleted) members already carrying
583	     * this household id, using each member's effective (already-capped) level as returned to
584	     * clients. Returns {@code null} when the household has no existing member, so no cap applies.
585	     */
586	    private Integer householdMembershipLevelCap(String householdId) {
587	        if (householdId == null) {
588	            return null;
589	        }
590	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
591	            .filter(existing -> !existing.isDeleted())
592	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
593	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
594	            .max();
595	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
596	    }
597	
598	    /**
599	     * Find an existing owner that this new owner is a possible (soft) duplicate of: one whose
600	     * {@code soundex(lastName)} and postcode match the new owner's while its identity key differs (so
601	     * the two are not the same identity, which would already have been rejected as a 409). When
602	     * several existing owners match, the earliest (lowest id) is returned so the result is
603	     * deterministic. Returns {@code null} when there is no such owner — including when the new owner
604	     * has no last name or postcode, since a shared postcode is required to match.
605	     */
606	    private Owner findPossibleDuplicate(String lastName, String postcode, String identityKey) {
607	        if (isBlank(lastName) || isBlank(postcode)) {
608	            return null;
609	        }
610	        String soundex = IdentityKeys.soundex(lastName);
611	        return this.clinicService.findAllOwners().stream()
612	            .filter(existing -> !existing.isDeleted())
613	            .filter(existing -> soundex.equals(IdentityKeys.soundex(existing.getLastName())))
614	            .filter(existing -> postcode.equals(existing.getPostcode()))
615	            .filter(existing -> !identityKey.equals(
616	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getLastName())))
617	            .min(java.util.Comparator.comparing(Owner::getId))
618	            .orElse(null);
619	    }
