670	    /** Fixed public holidays the business-day roll skips. */
671	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
672	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
673	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
674	
675	    /**
676	     * Roll a date forward onto a business day: Saturdays, Sundays and listed public holidays are
677	     * advanced one day at a time until a non-weekend, non-holiday day is reached, while an ordinary
678	     * business day is returned unchanged. Used so the effective registration date (whether supplied
679	     * or defaulted) always falls on a business day.
680	     */
681	    private static LocalDate toBusinessDay(LocalDate date) {
682	        while (isWeekendOrHoliday(date)) {
683	            date = date.plusDays(1);
684	        }
685	        return date;
686	    }
687	
688	    private static boolean isWeekendOrHoliday(LocalDate date) {
689	        return switch (date.getDayOfWeek()) {
690	            case SATURDAY, SUNDAY -> true;
691	            default -> PUBLIC_HOLIDAYS.contains(date);
692	        };
693	    }
694	
695	    /**
696	     * Build the unified member id for a new owner: {@code '<REGION><FY><HASH8><CHK>'} where REGION is
697	     * the region derived from the owner's postcode/city, FY is the 2-digit fiscal year of the
698	     * (business-day-adjusted) {@code registrationDate}, HASH8 is the first 8 upper-case hex characters
699	     * of {@code SHA-256(normalizedTelephone + lastName)}, and CHK is a single Luhn check digit (0-9)
700	     * computed over the digits contained in the {@code '<REGION><FY><HASH8>'} base
701	     * (e.g. {@code 'NSW261A2B3C4D9'}).
702	     */
703	    private static String memberId(String region, LocalDate registrationDate,
704	                                   String normalizedTelephone, String lastName) {
705	        String fy = String.format("%02d",
706	            OwnerMapper.fiscalYearStart(registrationDate) % 100);
707	        String hash8 = hash8(normalizedTelephone + (lastName == null ? "" : lastName));
708	        String base = region + fy + hash8;
709	        return base + luhnCheckDigit(base);
710	    }
711	
712	    /**
713	     * Compute a single Luhn check digit (0-9) over the digit characters contained in {@code value};
714	     * non-digit characters (e.g. the region's letters or the hex letters of HASH8) are skipped.
715	     */
716	    private static int luhnCheckDigit(String value) {
717	        int sum = 0;
718	        boolean dbl = true;
719	        for (int i = value.length() - 1; i >= 0; i--) {
720	            char c = value.charAt(i);
721	            if (c < '0' || c > '9') {
722	                continue;
723	            }
724	            int d = c - '0';
725	            if (dbl) {
726	                d *= 2;
727	                if (d > 9) {
728	                    d -= 9;
729	                }
730	            }
731	            sum += d;
732	            dbl = !dbl;
733	        }
734	        return (10 - (sum % 10)) % 10;
735	    }
736	
737	    /**
738	     * Ensure the computed member id is unique across existing owners. When {@code base} is already
739	     * free it is returned unchanged; otherwise {@code '-<n>'} is appended using the smallest {@code n}
740	     * of 2 or more that produces a value no existing owner already carries.
741	     */
742	    private String deduplicateMemberId(String base) {
743	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
744	            .map(Owner::getMemberId)
745	            .filter(java.util.Objects::nonNull)
746	            .collect(java.util.stream.Collectors.toSet());
747	        if (!inUse.contains(base)) {
748	            return base;
749	        }
750	        int n = 2;
751	        while (inUse.contains(base + "-" + n)) {
752	            n++;
753	        }
754	        return base + "-" + n;
755	    }
756	
757	    /**
758	     * First 8 upper-case hex characters of {@code SHA-256(input)}.
759	     */
760	    private static String hash8(String input) {
761	        try {
762	            byte[] digest = MessageDigest.getInstance("SHA-256")
763	                .digest(input.getBytes(StandardCharsets.UTF_8));
764	            StringBuilder sb = new StringBuilder(digest.length * 2);
765	            for (byte b : digest) {
766	                sb.append(String.format("%02x", b));
767	            }
768	            return sb.substring(0, 8).toUpperCase();
769	        }
770	        catch (NoSuchAlgorithmException e) {
771	            throw new IllegalStateException("SHA-256 not available", e);
772	        }
773	    }
774	
775	    /**
776	     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
777	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
778	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
779	     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
780	     * mapper's locality derivation, so the customer code's region segment and the owner's locality
781	     * always agree.
782	     */
783	    private static String deriveRegion(String postcode, String city) {
784	        if (postcode != null && postcode.matches("\\d{4}")) {
785	            int value = Integer.parseInt(postcode);
786	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
787	                int[] range = entry.getValue();
788	                if (value >= range[0] && value <= range[1]) {
789	                    return entry.getKey();
790	                }
791	            }
792	        }
793	        if (city == null) {
794	            return "UNKNOWN";
795	        }
796	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
797	    }
798	
799	    /**
800	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
801	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
802	     * and accepts any 4-digit postcode.
803	     */
804	    private static final Map<String, String> CITY_REGION = Map.of(
805	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
806	
807	    /**
808	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
809	     * Each entry is a two-element {@code {low, high}} array.
810	     */
811	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
812	        "NSW", new int[] {2000, 2099},
813	        "VIC", new int[] {3000, 3099},
814	        "QLD", new int[] {4000, 4099});
815	
816	    /**
817	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
818	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
819	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
820	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
821	     * 4-digit postcode. A malformed or out-of-range postcode throws an
822	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
823	     */
824	    private static void validatePostcode(String city, String postcode) {
825	        if (postcode == null || postcode.isEmpty()) {
826	            return;
827	        }
828	        if (!postcode.matches("\\d{4}")) {
829	            throw new InvalidOwnerFieldsException(List.of("postcode"));
830	        }
831	        String region = city == null ? null : CITY_REGION.get(city);
832	        if (region == null) {
833	            return;
834	        }
835	        int[] range = REGION_POSTCODES.get(region);
836	        int value = Integer.parseInt(postcode);
837	        if (value < range[0] || value > range[1]) {
838	            throw new InvalidOwnerFieldsException(List.of("postcode"));
839	        }
840	    }
841	
842	    /**
843	     * Required national-number length for each E.164 country calling code we validate: a
844	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
845	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
846	     */
847	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
848	        "1", 10,
849	        "61", 9);
850	
851	    /**
852	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
853	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
854	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
855	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
856	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
857	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
858	     * rejected with a 400.
859	     */
860	    private static String toE164(String raw) {
861	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
862	        boolean hasCountryCode = cleaned.startsWith("+");
863	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
864	        if (!digits.matches("\\d+")) {
865	            throw new InvalidOwnerFieldsException(List.of("telephone"));
866	        }
867	        if (!hasCountryCode) {
868	            if (digits.startsWith("0")) {
869	                digits = digits.substring(1);
870	            }
871	            digits = "61" + digits;
872	        }
873	        if (digits.length() < 8 || digits.length() > 15) {
874	            throw new InvalidOwnerFieldsException(List.of("telephone"));
875	        }
876	        // For a recognised country code, the national number (the digits after the code) must be
877	        // exactly the expected length for that country. Match the longest known code so a shorter
878	        // code that is a prefix of another cannot mask it.
879	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
880	            if (digits.length() <= codeLength) {
881	                continue;
882	            }
883	            String countryCode = digits.substring(0, codeLength);
884	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
885	            if (requiredNationalLength != null) {
886	                if (digits.length() - codeLength != requiredNationalLength) {
887	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
888	                }
889	                break;
890	            }
891	        }
892	        return "+" + digits;
893	    }
894	
895	    /**
896	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
897	     * and a domain with at least one dot-separated label, none of which contain whitespace or
898	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
899	     */
900	    private static final Pattern EMAIL_PATTERN =
901	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
902	
903	    /**
904	     * Disposable email domains that are not accepted for an owner. An email whose domain (the part
905	     * after the {@code @}, compared case-insensitively) is on this blocklist is rejected with a 400.
906	     */
907	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
908	        "mailinator.com", "tempmail.com", "guerrillamail.com");
909	
910	    /**
911	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
912	     * supplied (the field is optional). When supplied it must be a syntactically valid address whose
913	     * domain is not on the disposable-domain blocklist, otherwise an
914	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400. A valid
915	     * address is returned lower-cased.
916	     */
917	    private static String normalizeEmail(String email) {
918	        if (email == null || email.isEmpty()) {
919	            return null;
920	        }
921	        String trimmed = email.trim();
922	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
923	            throw new InvalidOwnerFieldsException(List.of("email"));
924	        }
925	        String normalized = trimmed.toLowerCase();
926	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
927	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
928	            throw new InvalidOwnerFieldsException(List.of("email"));
929	        }
930	        return normalized;
931	    }
932	}
