86	    private Integer membershipLevelCap;
87	
88	    @Column(name = "bulk_signup_warning")
89	    private Boolean bulkSignupWarning;
90	
91	    @Column(name = "capacity_warning")
92	    private Boolean capacityWarning;
93	
94	    @Column(name = "possible_duplicate")
95	    private Boolean possibleDuplicate;
96	
97	    @Column(name = "possible_duplicate_of")
98	    private Integer possibleDuplicateOf;
99	
100	    @Column(name = "deleted", nullable = false)
101	    private boolean deleted;
102	
103	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
104	    private Set<Pet> pets;
105	
106	    public String getTitle() {
107	        return this.title;
108	    }
109	
