1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
25	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
26	    @Mapping(target = "telephoneDisplay",
27	        expression = "java(telephoneDisplay(owner))")
28	    @Mapping(target = "membershipPoints",
29	        expression = "java(membershipPoints(owner))")
30	    @Mapping(target = "membershipLevel",
31	        expression = "java(membershipLevel(owner))")
32	    @Mapping(target = "locality",
33	        expression = "java(locality(owner))")
34	    @Mapping(target = "timezone",
35	        expression = "java(timezone(owner))")
36	    @Mapping(target = "contactPreference",
37	        expression = "java(contactPreference(owner))")
38	    @Mapping(target = "identityKey",
39	        expression = "java(identityKey(owner))")
40	    @Mapping(target = "ageBand",
41	        expression = "java(ageBand(owner))")
42	    @Mapping(target = "fiscalYear",
43	        expression = "java(fiscalYear(owner))")
44	    @Mapping(target = "salutation",
45	        expression = "java(salutation(owner))")
46	    @Mapping(target = "selfLink",
47	        expression = "java(selfLink(owner))")
48	    @Mapping(target = "ownerSegment",
49	        expression = "java(ownerSegment(owner))")
50	    @Mapping(target = "sharesHousehold", ignore = true)
51	    OwnerDto toOwnerDto(Owner owner);
52	
53	    /**
54	     * Build the owner's canonical self link: '/api/owners/' followed by the owner's id. Returns null
55	     * when the owner has no id so an unsaved owner serializes cleanly.
56	     */
57	    default String selfLink(Owner owner) {
58	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
59	    }
60	
61	    /**
62	     * The set of known regions treated as METRO when deriving an owner's segment area.
63	     */
64	    java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
65	
66	    /**
67	     * Derive the owner's segment, formatted '&lt;TIER&gt;_&lt;AREA&gt;'. TIER is 'PREMIUM' when
68	     * {@link #membershipLevel(Owner)} is 3 or more, otherwise 'STANDARD'. AREA is 'METRO' when the
69	     * {@link #locality(Owner)} is a known region (NSW, VIC or QLD), otherwise 'REGIONAL'.
70	     */
71	    default String ownerSegment(Owner owner) {
72	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
73	        String area = METRO_REGIONS.contains(locality(owner)) ? "METRO" : "REGIONAL";
74	        return tier + "_" + area;
75	    }
76	
77	    /**
78	     * Build the owner's salutation: the honorific title followed by a single space and the last name
79	     * (e.g. 'DR Who') when a title is present, or just the last name when no title was supplied. A
80	     * blank title is treated as absent.
81	     */
82	    default String salutation(Owner owner) {
83	        String lastName = owner.getLastName();
84	        String title = owner.getTitle();
85	        if (title == null || title.trim().isEmpty()) {
86	            return lastName;
87	        }
88	        return title + " " + lastName;
89	    }
90	
91	    /**
92	     * Derive the owner's age band from the supplied birthDate, evaluated against the owner's
93	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18 to 64 inclusive, and 'SENIOR' when
94	     * 65 or older. Returns null when no birthDate was supplied (or no registrationDate is available)
95	     * so owners without a birth date serialize cleanly.
96	     */
97	    default String ageBand(Owner owner) {
98	        java.time.LocalDate birthDate = owner.getBirthDate();
99	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
100	        if (birthDate == null || registrationDate == null) {
101	            return null;
102	        }
103	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
104	        if (age < 18) {
105	            return "MINOR";
106	        }
107	        if (age < 65) {
108	            return "ADULT";
109	        }
110	        return "SENIOR";
111	    }
112	
113	    /**
114	     * The E.164 country calling codes whose split from the national number is recognised when
115	     * formatting {@code telephoneDisplay} (matching the codes validated on create). The longest
116	     * matching code wins so a shorter code that is a prefix of another cannot mask it.
117	     */
118	    java.util.Set<String> KNOWN_COUNTRY_CODES = java.util.Set.of("1", "61");
119	
120	    /**
121	     * Format the stored E.164 telephone for humans: the '+' and country calling code, a space, then
122	     * the national digits grouped in threes (e.g. '+61412345678' -&gt; '+61 412 345 678'). The
123	     * country code is split off using the recognised calling codes; when none matches, a single-digit
124	     * code is assumed so the value is still rendered as '+&lt;code&gt; &lt;grouped national&gt;'.
125	     * Returns the stored value unchanged when it is null or not in E.164 form.
126	     */
127	    default String telephoneDisplay(Owner owner) {
128	        String telephone = owner.getTelephone();
129	        if (telephone == null || !telephone.startsWith("+")) {
130	            return telephone;
131	        }
132	        String digits = telephone.substring(1);
133	        if (!digits.matches("\\d+")) {
134	            return telephone;
135	        }
136	        String countryCode = digits.substring(0, 1);
137	        String national = digits.substring(1);
138	        for (int codeLength = Math.min(3, digits.length() - 1); codeLength >= 1; codeLength--) {
139	            String candidate = digits.substring(0, codeLength);
140	            if (KNOWN_COUNTRY_CODES.contains(candidate)) {
141	                countryCode = candidate;
142	                national = digits.substring(codeLength);
143	                break;
144	            }
145	        }
146	        StringBuilder grouped = new StringBuilder();
147	        for (int i = 0; i < national.length(); i++) {
148	            if (i > 0 && i % 3 == 0) {
149	                grouped.append(' ');
150	            }
151	            grouped.append(national.charAt(i));
152	        }
153	        return "+" + countryCode + " " + grouped;
154	    }
155	
156	    /**
157	     * Derive the owner's identity key, the single value into which all duplicate detection is
158	     * consolidated: the full lower-case hex SHA-256 over
159	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. Two owners are
160	     * duplicates only when their whole identity keys are equal. A null email or last name contributes
161	     * an empty segment.
162	     */
163	    default String identityKey(Owner owner) {
164	        return IdentityKeys.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
165	    }
166	
167	    /**
168	     * Determine the owner's preferred contact channel: 'EMAIL' when an email address is present,
169	     * otherwise 'PHONE'.
170	     */
171	    default String contactPreference(Owner owner) {
172	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
173	        return hasEmail ? "EMAIL" : "PHONE";
174	    }
175	
176	    /**
177	     * The calendar year in which the fiscal year containing {@code date} starts. The fiscal year
178	     * starts on 1 July, so dates in July through December map to their own calendar year while
179	     * dates in January through June map to the previous calendar year.
180	     */
181	    static int fiscalYearStart(java.time.LocalDate date) {
182	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
183	            ? date.getYear() : date.getYear() - 1;
184	    }
185	
186	    /**
187	     * Derive the owner's fiscal year from the (business-day-adjusted) registrationDate, formatted
188	     * 'FY&lt;YY&gt;' where YY is the last two digits of the fiscal year's starting calendar year. The
189	     * fiscal year starts on 1 July. Returns null when no registrationDate is available so owners
190	     * without one serialize cleanly.
191	     */
192	    default String fiscalYear(Owner owner) {
193	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
194	        if (registrationDate == null) {
195	            return null;
196	        }
197	        return String.format("FY%02d", fiscalYearStart(registrationDate) % 100);
198	    }
199	
200	    /**
201	     * Compute the owner's membership points. Starts at 0; add 2 when an email address is present;
202	     * add 1 when the owner has no namesakes (namesakeCount is 0); add 2 for a household of 3 or more
203	     * (householdSize); add 3 for tenure of at least one elapsed fiscal year, measured as the number
204	     * of fiscal-year starts (1 July) between the registrationDate and the current date. Because a
205	     * newly created owner has zero elapsed fiscal years, a new owner never earns the tenure points.
206	     */
207	    default Integer membershipPoints(Owner owner) {
208	        int points = 0;
209	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
210	        if (hasEmail) {
